mapper.select:
SELECT mdr.id, mdr.audit_status, mdr.audit_man_day,
       mdr.create_date, mdr.create_man, mdr.create_man_id,
       md.week_start_date, md.week_end_date,
       p.pm, p.pm_id, p.name projectName
FROM man_day_report mdr
    LEFT JOIN man_day md on mdr.man_day_id = md.id
    LEFT JOIN project p on md.project_id = p.id

    AND p.name like concat('%',#{projectName},'%')
    AND mdr.reject_reason like concat('%',#{rejectReason},'%')

        AND mdr.audit_status in

            #{item}



        AND mdr.create_man_id in

            #{item}



        AND p.pm_id in

            #{item}



        AND mdr.create_date >= #{createDateStart}
        AND mdr.create_date <= #{createDateEnd}


        AND md.week_start_date >= #{weekStartDate}
        AND md.week_end_date <= #{weekEndDate}

SELECT * FROM man_day_report WHERE id in
#{item}
AND is_deleted = false
